document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('.phbio-aab').forEach(x=>x.classList.add('is-ready'));document.querySelectorAll('.phbio-catalog').forEach(root=>{const cards=[...root.querySelectorAll('.phbio-card')],filters=root.querySelector('.phbio-filters'),sentinel=root.querySelector('.phbio-sentinel');let selected=cards,shown=20;function render(){cards.forEach(c=>{const visible=selected.includes(c)&&selected.indexOf(c)<shown;c.classList.toggle('phbio-deferred',!visible);c.classList.toggle('phbio-revealed',visible);});sentinel?.classList.toggle('hidden',shown>=selected.length);}filters?.addEventListener('click',e=>{const b=e.target.closest('.phbio-pill');if(!b)return;filters.querySelectorAll('.phbio-pill').forEach(x=>x.classList.toggle('active',x===b));selected=b.dataset.cat==='all'?cards:cards.filter(c=>[...c.querySelectorAll('[data-cat]')].some(t=>t.dataset.cat===b.dataset.cat));shown=20;render();});if(sentinel)new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){shown+=20;render();}},{rootMargin:'400px'}).observe(sentinel);render();});});document.addEventListener('click',e=>{const a=e.target.closest('[data-clone-add],.add_to_cart_button');if(a){e.preventDefault();e.stopImmediatePropagation();alert('Preview only: checkout is not connected.');}},true);document.addEventListener('submit',e=>{e.preventDefault();e.stopImmediatePropagation();alert('Preview only: this form is not connected to a service.');},true);